    "A key for this plugin was saved in an older format that Tovu no longer reads. Enter it again here and save.": "حُفظ مفتاح لهذه الإضافة بتنسيق قديم لم يعد Tovu يقرؤه. أدخله هنا مرة أخرى واحفظ.",
    "Saved keys for this plugin can't be read on this machine. Enter them again here and save.": "لا يمكن قراءة المفاتيح المحفوظة لهذه الإضافة على هذا الجهاز. أدخلها هنا مرة أخرى واحفظ.",
    "Saved — leave blank to keep": "محفوظ — اتركه فارغًا للإبقاء عليه",
