    "Needs {capabilities}": "تحتاج إلى {capabilities}",
    "{plugin} needs {capability}": "{plugin} تحتاج إلى {capability}",
    "Update": "تحديث",
    "Updating…": "جارٍ التحديث…",
    "Upload a newer version of this plugin as a .zip or a folder. It keeps its memory and stays on or off as it is now.": "ارفع إصدارًا أحدث من هذه الإضافة كملف .zip أو مجلد. تحتفظ بذاكرتها وتبقى مفعّلة أو معطّلة كما هي الآن.",
    "{name} is updated.": "تم تحديث {name}.",
    "You added this package. Turning it off keeps its files and memory.": "أنت من أضاف هذه الحزمة. إيقافها يُبقي ملفاتها وذاكرتها.",
    "Other enabled plugins rely on it:": "تعتمد عليها إضافات مفعّلة أخرى:",
    "This plugin changed since this page loaded. Reload the page and try again.": "تغيّرت هذه الإضافة منذ تحميل هذه الصفحة. أعد تحميل الصفحة وحاول مرة أخرى.",
    "This package is an older version than the one installed.": "هذه الحزمة إصدار أقدم من الإصدار المثبّت.",
    "This package is a different plugin.": "هذه الحزمة إضافة مختلفة.",
    "Plugins that ship with Tovu update with Tovu.": "الإضافات المرفقة مع Tovu تُحدَّث مع Tovu.",
    "An earlier update is still being recovered. Restart Tovu and try again.": "لا يزال تحديث سابق قيد الاستعادة. أعد تشغيل Tovu وحاول مرة أخرى.",
    "Replaces the installed version with a newer one. Older versions are refused.": "يستبدل الإصدار المثبت بإصدار أحدث. تُرفض الإصدارات الأقدم.",
    "The new version's MCP servers could not be set up; the previous version was restored.": "تعذّر إعداد خوادم MCP للإصدار الجديد؛ تمت استعادة الإصدار السابق.",
    "This plugin is not made for this Tovu version.": "هذه الإضافة غير مصممة لهذا الإصدار من Tovu.",
    "Could not update the plugin. Try again.": "تعذّر تحديث الإضافة. حاول مرة أخرى.",
    "This package has no release version to compare.": "لا تحتوي هذه الحزمة على إصدار للمقارنة.",
    "Same version number as the installed one, with different contents.": "رقم الإصدار نفسه للمثبّت، لكن المحتوى مختلف.",
