    "Other enabled plugins rely on it:": "有効な他のプラグインがこれに依存しています:",
    "This plugin changed since this page loaded. Reload the page and try again.": "このページを読み込んだ後にプラグインが変更されました。ページを再読み込みして、もう一度お試しください。",
