    "Upload a newer version of this plugin as a .zip or a folder. It keeps its memory and stays on or off as it is now.": "Prześlij nowszą wersję tej wtyczki jako .zip lub folder. Zachowa swoją pamięć i pozostanie włączona lub wyłączona tak jak teraz.",
    "{name} is updated.": "{name}: zaktualizowano.",
    "You added this package. Turning it off keeps its files and memory.": "Ten pakiet dodałeś Ty. Wyłączenie go zachowuje jego pliki i pamięć.",
    "Other enabled plugins rely on it:": "Inne włączone wtyczki od niej zależą:",
    "This plugin changed since this page loaded. Reload the page and try again.": "Ta wtyczka zmieniła się od załadowania tej strony. Odśwież stronę i spróbuj ponownie.",
