    "An earlier update is still being recovered. Restart Tovu and try again.": "Wcześniejsza aktualizacja jest nadal przywracana. Uruchom ponownie Tovu i spróbuj ponownie.",
    "Replaces the installed version with a newer one. Older versions are refused.": "Zastępuje zainstalowaną wersję nowszą. Starsze wersje są odrzucane.",
