    "Replaces the installed version with a newer one. Older versions are refused.": "แทนที่เวอร์ชันที่ติดตั้งด้วยเวอร์ชันที่ใหม่กว่า เวอร์ชันที่เก่ากว่าจะถูกปฏิเสธ",
