    // Agent Plugins / Plugins tab copy previously translated only in `es`
    "Integrations": "การผสานการทำงาน",
    "Downloaded Agent Plugins": "ปลั๊กอินเอเจนต์ที่ดาวน์โหลดแล้ว",
    "Every package downloaded to this workspace.": "แพ็กเกจทุกรายการที่ดาวน์โหลดมายังพื้นที่ทำงานนี้",
    "No Agent Plugins are enabled for this workspace.": "ไม่มีปลั๊กอินเอเจนต์ที่เปิดใช้งานสำหรับพื้นที่ทำงานนี้",
    "These plugins are enabled. Their skills reach the assistant's prompt on every run.": "ปลั๊กอินเหล่านี้เปิดใช้งานอยู่ สกิลของปลั๊กอินจะไปถึงพรอมป์ของผู้ช่วยทุกครั้งที่ทำงาน",
    "Until then, the downloaded packages on the Downloaded tab are the ones Tovu ships.": "ระหว่างนี้ แพ็กเกจที่ดาวน์โหลดแล้วในแท็บดาวน์โหลดแล้วคือแพ็กเกจที่มาพร้อมกับ Tovu",
    "An installed plugin sits inert until you enable it. Enabling one puts its skills in the assistant's prompt for every run.": "ปลั๊กอินที่ติดตั้งแล้วจะไม่ทำงานจนกว่าคุณจะเปิดใช้งาน เมื่อเปิดใช้งาน สกิลของปลั๊กอินจะอยู่ในพรอมป์ของผู้ช่วยทุกครั้งที่ทำงาน",
    "No Agent Plugins are installed in this workspace.": "ไม่มีปลั๊กอินเอเจนต์ที่ติดตั้งในพื้นที่ทำงานนี้",
    "Agent Plugin Marketplace": "ตลาดกลางปลั๊กอินเอเจนต์",
    "A future place to discover portable Agent Plugins.": "พื้นที่ในอนาคตสำหรับค้นหาปลั๊กอินเอเจนต์ที่พกพาได้",
    "Nothing to browse yet": "ยังไม่มีอะไรให้เรียกดู",
    "Marketplace is planned for a future release. Tovu does not fetch, install, or list marketplace packages yet.": "ตลาดกลางมีแผนจะเปิดในรุ่นถัดไป ขณะนี้ Tovu ยังไม่ดึง ติดตั้ง หรือแสดงรายการแพ็กเกจจากตลาดกลาง",
    "Read the package format": "อ่านรูปแบบแพ็กเกจ",
    "Package format:": "รูปแบบแพ็กเกจ:",
    "Enabled plugins extend what this site can do.": "ปลั๊กอินที่เปิดใช้งานช่วยขยายสิ่งที่เว็บไซต์นี้ทำได้",
    "Built-in plugins ship with Tovu itself and have no on-disk files to remove.": "ปลั๊กอินในตัวมาพร้อมกับ Tovu และไม่มีไฟล์บนดิสก์ให้ลบ",
    "Turn a plugin off on Installed before removing it.": "ปิดปลั๊กอินในแท็บติดตั้งแล้วก่อนลบ",
    "Marketplace is planned for a future release. Tovu does not fetch, list, or install plugins from a marketplace yet.": "ตลาดกลางมีแผนจะเปิดในรุ่นถัดไป ขณะนี้ Tovu ยังไม่ดึง แสดงรายการ หรือติดตั้งปลั๊กอินจากตลาดกลาง",
    "Install a plugin by placing its files in this site's plugin install directory.": "ติดตั้งปลั๊กอินโดยวางไฟล์ของปลั๊กอินในไดเรกทอรีติดตั้งปลั๊กอินของเว็บไซต์นี้",
    // Plugin-owned admin surface frame notices (2026-10-20).
    "This view left its page and was closed. Close and reopen the plugin to use it again.": "มุมมองนี้ออกจากหน้าของตัวเองและถูกปิดแล้ว ให้ปิดปลั๊กอินแล้วเปิดใหม่เพื่อใช้งานอีกครั้ง",
    "Could not open this view. Close and reopen the plugin to try again.": "ไม่สามารถเปิดมุมมองนี้ได้ ให้ปิดปลั๊กอินแล้วเปิดใหม่เพื่อลองอีกครั้ง",
    "Sign-in opens in your browser.": "การลงชื่อเข้าใช้จะเปิดในเบราว์เซอร์ของคุณ",
    "Continue to sign-in": "ไปที่การลงชื่อเข้าใช้",
