    "A key for this plugin was saved in an older format that Tovu no longer reads. Enter it again here and save.": "इस प्लगइन की एक कुंजी पुराने फ़ॉर्मैट में सहेजी गई थी, जिसे Tovu अब नहीं पढ़ता। इसे यहाँ फिर से दर्ज करें और सहेजें।",
    "Saved keys for this plugin can't be read on this machine. Enter them again here and save.": "इस प्लगइन की सहेजी गई कुंजियाँ इस मशीन पर पढ़ी नहीं जा सकतीं। उन्हें यहाँ फिर से दर्ज करें और सहेजें।",
