    "Upload a newer version of this plugin as a .zip or a folder. It keeps its memory and stays on or off as it is now.": "इस प्लगिन का नया संस्करण .zip या फ़ोल्डर के रूप में अपलोड करें। इसकी मेमोरी बनी रहती है और यह अभी की तरह चालू या बंद रहता है।",
    "{name} is updated.": "{name} अपडेट हो गया।",
    "You added this package. Turning it off keeps its files and memory.": "यह पैकेज आपने जोड़ा है। बंद करने पर इसकी फ़ाइलें और मेमोरी बनी रहती हैं।",
    "Other enabled plugins rely on it:": "चालू अन्य प्लगिन इस पर निर्भर हैं:",
    "This plugin changed since this page loaded. Reload the page and try again.": "इस पेज के लोड होने के बाद यह प्लगिन बदल गया। पेज फिर से लोड करें और फिर से कोशिश करें।",
