    "Plugins that ship with Tovu update with Tovu.": "Tovu के साथ आने वाले प्लगिन Tovu के साथ ही अपडेट होते हैं।",
    "An earlier update is still being recovered. Restart Tovu and try again.": "पिछला अपडेट अभी भी रिकवर हो रहा है। Tovu को रीस्टार्ट करें और फिर से कोशिश करें।",
    "Replaces the installed version with a newer one. Older versions are refused.": "इंस्टॉल किए गए संस्करण को नए संस्करण से बदलता है। पुराने संस्करण अस्वीकार किए जाते हैं।",
    "The new version's MCP servers could not be set up; the previous version was restored.": "नए संस्करण के MCP सर्वर सेट अप नहीं हो सके; पिछला संस्करण बहाल कर दिया गया।",
    "This plugin is not made for this Tovu version.": "यह प्लगिन Tovu के इस संस्करण के लिए नहीं बना है।",
