    "This removes it for all workspaces on this site. You can restore it from the Trash for 60 days.": "यह इसे इस साइट के सभी कार्यस्थानों से हटा देता है। आप इसे 60 दिनों तक ट्रैश से पुनर्स्थापित कर सकते हैं।",
