    "These plugins are enabled. Their skills reach the assistant's prompt on every run.": "ये प्लगिन सक्षम हैं। इनके स्किल हर रन में असिस्टेंट के प्रॉम्प्ट तक पहुँचते हैं।",
    "Until then, the downloaded packages on the Downloaded tab are the ones Tovu ships.": "तब तक, डाउनलोड किया गया टैब पर डाउनलोड किए गए पैकेज वही हैं जो Tovu के साथ आते हैं।",
    "An installed plugin sits inert until you enable it. Enabling one puts its skills in the assistant's prompt for every run.": "इंस्टॉल किया गया प्लगिन तब तक निष्क्रिय रहता है जब तक आप उसे सक्षम नहीं करते। सक्षम करने पर उसके स्किल हर रन में असिस्टेंट के प्रॉम्प्ट में जुड़ जाते हैं।",
    "No Agent Plugins are installed in this workspace.": "इस वर्कस्पेस में कोई एजेंट प्लगिन इंस्टॉल नहीं है।",
